// Show the pull request for the session's branch in the prompt status row as
// "#123", colored by state the way GitHub does: green open, purple merged, red
// closed, grey draft. Click it to open the PR in the browser.
//
// Renders into the session_prompt_footer slot, which only exists in the
// local opencode build (feat/tui-prompt-footer-slot). On a host without the
// slot this registers and simply never shows.
//
// The lookup is `gh pr list --head <branch>` run in the session's directory, so
// a session working in a worktree shows that worktree's PR. `gh pr view` is not
// used because it misses PRs opened from a fork unless the branch tracks the
// fork remote. Refreshed when the
// session goes idle (an agent turn may have pushed or opened the PR) and on a
// timer for state changes made elsewhere (merged on GitHub, say).
//
// Options (tui.json -> ["./tui-plugins/pr-footer.js", { ... }]):
//   interval_ms  background refresh period (default 60000)

import { createElement, createTextNode, effect, insert, insertNode, setProp, createComponent } from "@opentui/solid"
import { createEffect, createSignal, onCleanup, Show } from "solid-js"
import { execFile } from "node:child_process"
import { promisify } from "node:util"

const run = promisify(execFile)

const DEFAULTS = { interval_ms: 60_000 }

// Several TUIs can sit on the same branch; one gh call serves them all.
const CACHE_MS = 15_000
const cache = new Map()

const SKIP_BRANCHES = new Set(["HEAD", "main", "master", "dev", "develop"])

async function branchOf(dir) {
  const { stdout } = await run("git", ["-C", dir, "rev-parse", "--abbrev-ref", "HEAD"])
  return stdout.trim()
}

async function lookup(dir) {
  const branch = await branchOf(dir).catch(() => "")
  if (!branch || SKIP_BRANCHES.has(branch)) return undefined
  const key = `${dir}\0${branch}`
  const hit = cache.get(key)
  if (hit && Date.now() - hit.at < CACHE_MS) return hit.value
  const value = run(
    "gh",
    [
      "pr",
      "list",
      "--head",
      branch,
      "--state",
      "all",
      "--limit",
      "1",
      "--json",
      "number,url,state,isDraft",
    ],
    { cwd: dir, timeout: 15_000 },
  )
    .then(({ stdout }) => {
      const pr = JSON.parse(stdout)[0]
      if (!pr) return undefined
      return {
        number: pr.number,
        url: pr.url,
        state: pr.isDraft && pr.state === "OPEN" ? "draft" : pr.state.toLowerCase(),
      }
    })
    .catch(() => undefined)
  cache.set(key, { at: Date.now(), value })
  return value
}

function PrFooter(props) {
  const { api, options } = props
  const [pr, setPr] = createSignal()
  let generation = 0

  const refresh = async (sessionID) => {
    const mine = ++generation
    const dir = api.state.session.get(sessionID)?.directory ?? api.state.path.directory
    const value = await lookup(dir)
    if (mine === generation) setPr(value)
  }

  createEffect(() => {
    const sessionID = props.sessionID
    setPr(undefined)
    void refresh(sessionID)
  })

  const timer = setInterval(() => void refresh(props.sessionID), options.interval_ms)
  const off = api.event.on("session.idle", (event) => {
    if (event.properties?.sessionID !== props.sessionID) return
    cache.clear()
    void refresh(props.sessionID)
  })
  onCleanup(() => {
    generation++
    clearInterval(timer)
    off()
  })

  // GitHub's merged purple; themes have no color that reliably reads as purple.
  const MERGED = "#8957e5"
  const stateColor = (p) => {
    const t = api.theme.current
    if (p.state === "merged") return MERGED
    if (p.state === "closed") return t.error
    if (p.state === "draft") return t.textMuted
    return t.success
  }

  // The slot host inserts whatever this returns from inside a tracked effect.
  // Returning the Show (a reactive function) directly would let pr() changes
  // re-run that effect, which recreates this component and loops forever; a
  // static box keeps the reactivity inside.
  const root = createElement("box")
  insert(root, createComponent(Show, {
    get when() {
      return pr()
    },
    keyed: true,
    children: (p) => {
      const text = createElement("text")
      setProp(text, "wrapMode", "none")
      setProp(text, "onMouseUp", () => void run("open", [p.url]).catch(() => {}))
      insert(text, `#${p.number}`)
      effect((prev) => setProp(text, "fg", stateColor(p), prev))
      return text
    },
  }))
  return root
}

const tui = async (api, rawOptions) => {
  if (typeof api.slots?.register !== "function") return
  const options = { ...DEFAULTS, ...(rawOptions ?? {}) }
  api.slots.register({
    order: 100,
    slots: {
      session_prompt_footer(_ctx, props) {
        return createComponent(PrFooter, {
          api,
          options,
          get sessionID() {
            return props.session_id
          },
        })
      },
    },
  })
}

export default { id: "pr-footer", tui }
